CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth;
CREATE EXTENSION pgcrypto;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('test.uid',true),'')::uuid $$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_build_object('role',current_setting('test.role',true)) $$;
GRANT USAGE ON SCHEMA auth TO anon,authenticated,service_role;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE TABLE organizations(id uuid PRIMARY KEY, settings jsonb DEFAULT '{}', deleted_at timestamptz);
CREATE TABLE branches(id uuid PRIMARY KEY, organization_id uuid, name text, is_active boolean DEFAULT true, deleted_at timestamptz);
CREATE TABLE branch_members(user_id uuid, branch_id uuid, is_active boolean DEFAULT true, deleted_at timestamptz);
CREATE TABLE owners(id uuid PRIMARY KEY, organization_id uuid, portal_user_id uuid, email text, is_active boolean DEFAULT true, deleted_at timestamptz);
CREATE TABLE patients(id uuid PRIMARY KEY, organization_id uuid, owner_id uuid, name text, is_active boolean DEFAULT true, is_deceased boolean DEFAULT false, deleted_at timestamptz);
CREATE TABLE appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid, branch_id uuid, assigned_user_id uuid, patient_id uuid, owner_id uuid, starts_at timestamptz, ends_at timestamptz, status text, appointment_type text, title text, cancellation_reason text, deleted_at timestamptz);
CREATE TABLE vaccinations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid, owner_id uuid, patient_id uuid, vaccine_name text, administered_at date, next_due_at date, created_at timestamptz DEFAULT now(), deleted_at timestamptz);
CREATE TABLE owner_portal_invites(organization_id uuid, token_hash text, expires_at timestamptz, accepted_at timestamptz, revoked_at timestamptz);
CREATE TABLE professional_time_blocks(organization_id uuid, branch_id uuid, user_id uuid, starts_at timestamptz, ends_at timestamptz, deleted_at timestamptz);
CREATE TABLE professional_schedules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slot_duration_minutes integer DEFAULT 30, organization_id uuid, branch_id uuid, user_id uuid, weekday smallint, start_time time, end_time time, allowed_appointment_types text[], is_active boolean DEFAULT true, deleted_at timestamptz);
CREATE FUNCTION get_user_organization_id() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('test.org',true),'')::uuid $$;
CREATE FUNCTION is_clinic_staff() RETURNS boolean LANGUAGE sql AS $$ SELECT current_setting('test.staff',true) = 'true' $$;
CREATE FUNCTION has_permission(text) RETURNS boolean LANGUAGE sql AS $$ SELECT current_setting('test.staff',true) = 'true' $$;
CREATE FUNCTION get_portal_owner_id() RETURNS uuid LANGUAGE sql SECURITY DEFINER AS $$ SELECT id FROM owners WHERE portal_user_id = auth.uid() AND deleted_at IS NULL AND is_active $$;
